const {h,mount,Column,Text,Table,Button,signal,data,action,calculate}=Sevra;

const incrementStock = action('incrementStock', {
  title: 'Increment Stock',
  inputs: {
    partId: { type: 'record', title: 'Part ID', required: true },
    currentStock: { type: 'decimal', title: 'Current Stock', required: true }
  }
}, async ({ partId, currentStock }) => {
  const newStock = await calculate('current + 1', { current: currentStock });
  const receipt = await data.transaction([{
    op: 'update',
    table: 'parts',
    id: partId,
    values: { stock: newStock }
  }]);
  return { updated: partId, newStock: newStock, receipt: receipt.token };
});

const search = signal('');
const selectedPart = signal(null);
const busy = signal(false);
const status = signal('');

const parts = await data.all('parts');

function App() {
  return h(Column, { gap: 12 },
    h(Text, { text: 'Stock Counter', size: 24, weight: 'bold' }),
    h(Table, {
      table: 'parts',
      label: 'Parts',
      search: search,
      columns: ['part', 'category', 'stock'],
      selection: selectedPart,
      onSelect: (e) => { selectedPart.value = e.value; status.value = ''; },
      height: 300
    }),
    h(Button, {
      title: 'Add 1',
      enabled: () => selectedPart.value !== null && !busy.value,
      onClick: async () => {
        if (busy.value) return;
        busy.value = true;
        try {
          const part = selectedPart.value;
          const result = await incrementStock({ partId: part.id, currentStock: part.values.stock });
          status.value = `Stock for ${part.values.part} updated to ${result.newStock}`;
          selectedPart.value = null;
        } catch (e) {
          status.value = e.message;
        } finally {
          busy.value = false;
        }
      }
    }),
    h(Text, { text: status, color: 'secondary' })
  );
}

mount(h(App));

